34|	}
35|	if in.RunAt != nil && in.DelaySeconds != nil {
36|		return nil, fmt.Errorf("run_at and delay_seconds are exclusive")
37|	}
38|	priority := 5
39|	if in.Priority != nil {
40|		priority = *in.Priority
41|	}
42|	if priority < 0 || priority > 9 {
43|		return nil, fmt.Errorf("priority must be 0–9")
44|	}
45|	max := int(q["max_attempts"].(int64))
46|	if in.MaxAttempts != nil {
47|		max = *in.MaxAttempts
48|	}
49|	if max < 1 {
50|		return nil, fmt.Errorf("max_attempts must be positive")
51|	}
52|	at := now
53|	if in.RunAt != nil {
54|		at = *in.RunAt
55|	}
56|	if in.DelaySeconds != nil {
57|		if *in.DelaySeconds < 0 || *in.DelaySeconds > jobs.MaxSeconds {
58|			return nil, fmt.Errorf("delay_seconds must be 0–%d", jobs.MaxSeconds)
