148|// objectPayload is the shared enqueue/schedule-template contract.
149|func objectPayload(raw json.RawMessage) (json.RawMessage, error) {
150|	if raw == nil {
151|		raw = json.RawMessage(`{}`)
152|	}
153|	raw = bytes.TrimSpace(raw)
154|	if len(raw) == 0 || raw[0] != '{' || !json.Valid(raw) {
