11|func Open(url string) (*Store, error) {
12|	d, e := sql.Open("postgres", url)
13|	if e != nil {
14|		return nil, e
15|	}
16|	d.SetMaxOpenConns(16)
17|	return &Store{d}, d.Ping()
18|}
19|func (s *Store) Rows(query string, args ...any) ([]map[string]any, error) {
20|	r, e := s.DB.Query(query, args...)
21|	if e != nil {
22|		return nil, e
23|	}
24|	defer r.Close()
25|	cols, e := r.Columns()
26|	if e != nil {
27|		return nil, e
28|	}
29|	out := []map[string]any{}
30|	for r.Next() {
31|		vals := make([]any, len(cols))
32|		ptr := make([]any, len(cols))
33|		for i := range vals {
34|			ptr[i] = &vals[i]
35|		}
36|		if e = r.Scan(ptr...); e != nil {
37|			return nil, e
38|		}
39|		m := map[string]any{}
40|		for i, k := range cols {
41|			v := vals[i]
42|			if b, ok := v.([]byte); ok {
43|				if k == "payload" || k == "result" || k == "body" {
44|					if json.Valid(b) {
45|						v = json.RawMessage(b)
46|					} else {
47|						v = string(b)
48|					}
49|				} else {
50|					v = string(b)
51|				}
52|			}
53|			m[k] = v
54|		}
55|		out = append(out, m)
56|	}
57|	return out, r.Err()
58|}
59|func (s *Store) One(query string, args ...any) (map[string]any, error) {
60|	r, e := s.Rows(query, args...)
61|	if e != nil {
62|		return nil, e
63|	}
64|	if len(r) == 0 {
65|		return nil, sql.ErrNoRows
66|	}
67|	return r[0], nil
